using namespace std;

struct NODE
{
	string KEY;
	string VALUE;
};


bool operator==(const NODE& a, const NODE& b)
{
	return a.KEY == b.KEY && a.VALUE == b.VALUE;
}


class HASH
{

	list<NODE> hash[10000];

public:

	void getvalue(string key, string value, bool met)
	{
		hash[gethash(key, met)].push_back({ key,value });
	}

	string takevalue(string key, bool met)
	{
		if (hash[gethash(key, met)].size() == 1) {
			return (hash[gethash(key, met)].begin())->VALUE;
		}
		else
			for (auto i = hash[gethash(key, met)].begin(); i != hash[gethash(key, met)].end(); i++)
				if (i->KEY == key) return i->VALUE;

		return "Value not found";
	}

	void deletevalue(string key, bool met)
	{
		hash[gethash(key, met)].remove({key,takevalue(key,met)});
	}

	int gethash(string key, bool met)
	{
		string numkey = "";
		long long pos = 0;
		if (met) {
			for (int i = 0; i < key.length(); i++)
			{
				numkey += to_string(key[i]);
			}
			for (int i = 0; i < numkey.length(); i += 4)
			{
				pos = (pos + stoi(numkey.substr(i, 4))) % 10000;
			}
			return pos;
		}
		else {
			for (int i = 0; i < key.length(); i++)
			{
				pos = pos * 1000 + key[i];
			}
			pos *= pos;
			return stoi(to_string(pos).substr(to_string(pos).length() / 2 - 2, 4));
		}
	}
};

