//Let G = (V,E) be a directed graph with n nodes and m edges. Two nodes u, v are said to be incomparable if there are no paths from u to v and from v to u.
//(a) Write code in C that constructs a struct that can answer in constant time if there is a path between two nodes u and v.

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct node {
    int data;
    struct node *next;
} node;

typedef struct graph {
    int numVertices;
    node **adjLists;
} graph;

node *createNode(int v) {
    node *newNode = malloc(sizeof(node));
    newNode->data = v;
    newNode->next = NULL;
    return newNode;
}

graph *createGraph(int vertices) {
    graph *graph = malloc(sizeof(graph));
    graph->numVertices = vertices;

    graph->adjLists = malloc(vertices * sizeof(node *));

    int i;
    for (i = 0; i < vertices; i++)
        graph->adjLists[i] = NULL;

    return graph;
}

void addEdge(graph *graph, int src, int dest) {
    node *newNode = createNode(dest);
    newNode->next = graph->adjLists[src];
    graph->adjLists[src] = newNode;
}

void printGraph(graph *graph) {
    int v;
    for (v = 0; v < graph->numVertices; v++) {
        node *temp = graph->adjLists[v];
        printf("\n Adjacency list of vertex %d\n ", v);
        while (temp) {
            printf("%d -> ", temp->data);
            temp = temp->next;
        }
        printf("\n");
    }
}

bool isPath(graph *graph, int src, int dest) {
    node *temp = graph->adjLists[src];
    while (temp) {
        if (temp->data == dest) {
            return true;
        }
        temp = temp->next;
    }
    return false;
}

int main() {
    graph *graph = createGraph(4);
    addEdge(graph, 0, 1);
    addEdge(graph, 0, 2);
    addEdge(graph, 1, 2);
    addEdge(graph, 2, 0);
    addEdge(graph, 2, 3);
    addEdge(graph, 3, 3);

    printGraph(graph);

    printf("\n%d", isPath(graph, 1, 3));
    printf("\n%d", isPath(graph, 3, 1));

    return 0;
}

